,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-----------------------------------------------------',
'--  To show P20_STATUS below percent graph:',
'--     Apperance',
'--     Item Display Position: Below Content',
'-----------------------------------------------------',
'declare',
'   v_percent    number := 0;',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   if :P20_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P20_UNIQID;',
'      v_fname := ''quick_report_exec_apx'' || v_uniqid || ''.pct'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         utl_file.get_line (v_file, v_percent);',
'         utl_file.fclose (v_file);',
'      end if;',
'   end if;',
'   return ''select ''|| v_percent || '' as pct1, '' || v_percent || '' as pct2 from dual'';',
'end;'))
,p_ajax_enabled=>'Y'
,p_query_row_template=>wwv_flow_api.id(26796945511449919)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'-'
