,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P21_PRC_Submit_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'---------------------------------------------',
'-- Invoke external program',
'---------------------------------------------',
'',
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2 (200);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'   v_uniqid     varchar2(30);',
'   v_appusr     varchar2(15);',
'   v_fname      varchar2(30);',
'   v_jobargs    varchar2(100);',
'',
'begin',
'   dbms_scheduler.drop_credential (''recuser_credential'', true);',
'   dbms_scheduler.create_credential (',
'      credential_name => ''recuser_credential'',',
'      username        => ''recuser'',',
'      password        => ''desAdmin1''',
'   );',
'   dbms_scheduler.create_job (',
'      job_name             => ''quick_report_job'',',
'      job_type             => ''executable'',',
'      number_of_arguments  => 1,',
'      job_action           => ''/home/sysoper/recuser/quick_reports/quick_report_exec.sh'',',
'      auto_drop            => true,',
'      credential_name      => ''recuser_credential''',
'   );',
'',
'--   :P21_SCRIPT_NAME := ''Siniestros_Pendientes_Municipios_Koralis_parm'';',
'   v_uniqid := dbms_session.unique_session_id;',
'   v_appusr := :APP_USER;',
'   v_jobargs := :P21_SCRIPT_NAME || '':'' || :P21_REP_DATE || '':'' || '':--sid='' || v_uniqid || '':--usr='' || v_appusr;',
'   dbms_scheduler.set_job_argument_value (''quick_report_job'', 1, v_jobargs);',
'   dbms_scheduler.enable (''quick_report_job'');',
'   -- Allow time for external program to reset Apex status --',
'   dbms_lock.sleep (1);',
'',
'   :P21_CLR_STATUS := null;',
'   :P21_STATUS := ''Connecting to database ...'';',
'   :P21_ENDIC := null;',
'   :P21_WARN := null;',
'   :P21_UNIQID := v_uniqid;',
'--   exception',
'--         when others then',
'--         raise_application_error (-20999, ''PROCESS ALREADY RUNNING - TRY LATER'');',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(21499737281721334)
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(21502850882721371)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P21_PRC_UpdateStatus_Btn'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   v_file       utl_file.file_type;',
'   v_line       varchar2(200);',
'   v_fname      varchar2(100);',
'   v_uniqid     varchar2(30);',
'   v_fexists    BOOLEAN;',
'   v_flength    number;',
'   v_fblksiz    binary_integer;',
'',
'begin',
'   if :P21_CLR_STATUS = ''Y'' then',
'      null;',
'   else',
'      execute immediate ''create or replace directory DIR_TMP as ''''/tmp'''''';',
'      v_uniqid := :P21_UNIQID;',
'      v_fname := ''quick_report_exec_apx'' || v_uniqid || ''.log'';',
'      utl_file.fgetattr (''DIR_TMP'', v_fname, v_fexists, v_flength, v_fblksiz);',
'      if v_fexists then',
'         v_file := utl_file.fopen (''DIR_TMP'', v_fname, ''R'');',
'         :P21_STATUS := null;',
'         loop',
'            utl_file.get_line (v_file, v_line);',
'            :P21_STATUS := :P21_STATUS || v_line || chr(13);',
'            if v_line like ''%ERROR:%'' or v_line like ''%WARNING:%'' or v_line like ''SP2-0%'' then',
'               :P21_WARN := ''Y'';',
'            end if;',
'         end loop;',
'      end if;',
'   end if;',
'   exception',
'      when no_data_found then',
'         utl_file.fclose (v_file);',
'         if v_line = ''Process completed.'' then',
'            if :P21_WARN = ''Y'' then',
'               :P21_ENDIC := ''#APP_IMAGES#icons8-warning-48.png'';',
'            else',
'               :P21_ENDIC := ''#APP_IMAGES#icons8-ok-48.png'';',
'            end if;',
'         end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(21500175521721336)
);
end;
